/* ai-composition */
& { --hub-ink: #1b1b1b; --hub-surface: #292929; --hub-surface-deep: #1e1e1e; --hub-text: #ffffff; --hub-muted: #a0a0a0; --hub-line: #333333; --hub-blue: #008080; --hub-red: #ff9900; --hub-team-left: #008080; --hub-team-right: #a5680c; border-radius: 0px; overflow: hidden;   }
& .scorebug { background: var(--hub-surface-deep); font-family: "Arial", Arial, sans-serif; color: var(--hub-text); }
& .scorebug-team { gap: 2%; padding: 0 2.5%; background: transparent; }
& .scorebug-team-blue { border-left: 0cqw solid var(--hub-blue); background: linear-gradient(105deg, var(--hub-team-left), color-mix(in srgb, var(--hub-team-left) 75%, var(--hub-surface-deep))); }
& .scorebug-team-red { border-right: 0cqw solid var(--hub-red); background: linear-gradient(255deg, var(--hub-team-right), color-mix(in srgb, var(--hub-team-right) 75%, var(--hub-surface-deep))); }
& .team-logo { visibility: hidden; flex-basis: 14%; width: 14%; }
& .team-lockup { flex: 1 1 19%; min-width: 0; }
& .team-code { font: 900 clamp(20px, 2.45cqw, 30px) "Impact", Arial, sans-serif; color: var(--hub-text); }
& .team-seed { color: var(--hub-muted); font-size: clamp(7px, .85cqw, 10px); }
& .team-gold { color: var(--hub-text); font: 900 clamp(18px, 2.1cqw, 25px) "Impact", Arial, sans-serif; }
& .team-objective { color: var(--hub-blue); font-size: clamp(12px, 1.45cqw, 17px); }
& .scorebug-team-red .team-objective { color: var(--hub-red); }
& .scorebug-team .team-objective, & .team-seed { color: var(--hub-text); }
& .scorebug-center { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: minmax(0, 1fr) 29%; gap: 0; padding: 0; place-items: center; background: var(--hub-surface); box-shadow: 1px 0 0 var(--hub-line) inset, -1px 0 0 var(--hub-line) inset; }
& .team-kills { min-width: 0; padding: 0 .1em; font: 900 3.75cqw/1.5 "Impact", Arial, sans-serif; color: var(--hub-text); }
& .scorebug-center .team-kills:first-child { grid-column: 1; grid-row: 1; }
& .scorebug-center .team-kills:nth-child(3) { grid-column: 2; grid-row: 1; }
& .score-divider { display: none; }
& .game-clock { position: static; grid-column: 1 / -1; grid-row: 2; width: 100%; height: 100%; min-width: 0; display: grid; place-items: center; padding: 0; transform: none; border: 0; background: var(--hub-ink); color: var(--hub-text); font: 900 clamp(10px, 1.85cqw, 22px)/1 "Impact", Arial, sans-serif; }
& .objective-row { gap: 6%; padding: 0 5%; background: var(--hub-ink); color: var(--hub-muted); font-size: clamp(9px, 1cqw, 12px); opacity: 1; border-top: 1px solid var(--hub-line); }
& .objective-row-blue { color: var(--hub-blue); } & .objective-row-red { color: var(--hub-red); }
